MATCH (source:PlantItem {tag: 'P-2704'})-[:line_to*1..]->(valve:Valve)-[:line_to*1..]->(equipment:Equipment)
RETURN DISTINCT valve.tag AS tag
ORDER BY tag;

MATCH (source:PlantItem {tag: 'P-2704'}), (valve:Valve)
WHERE EXISTS { (source)-[:line_to*1..]->(valve) }
  AND EXISTS { (valve)-[:line_to*1..]->(:Equipment) }
RETURN DISTINCT valve.tag AS tag
ORDER BY tag

MATCH (a:PlantItem {tag: 'P-2302'}), (b:PlantItem {tag: 'R-3301'})
RETURN EXISTS {
  MATCH (a) ((x)-[:line_to]->(y) WHERE x.tag <> 'GTV-23009' AND y.tag <> 'GTV-23009')+ (b)
} AS reachableWithoutGTV23009

MATCH (item:PlantItem {tag: 'PDI-9038'})-[:is_located_in]->(section:PlantSection)
RETURN DISTINCT section.unit_id AS unit_id
ORDER BY unit_id;

MATCH (v:PlantItem:SwingCheckValve {unit_id: '15'})
RETURN v.tag AS tag
ORDER BY tag;

MATCH (v:Valve)-[:line_to*1..]->(p:PlantItem {tag: 'P-401B'})
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (a:PlantItem {tag: 'EA-3901'}), (b:PlantItem {tag: 'V-3901'}), (v:Valve)
WHERE EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN count(DISTINCT v.tag) AS valve_count

MATCH (p:PlantItem:Pump {tag: 'P-4601A'}), (v:PlantItem:Valve), (e:PlantItem:Equipment)
WHERE EXISTS { (p)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(e) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (a:PlantItem {tag: 'EJ-4301A'}),
      (b:PlantItem {tag: 'E-4302'}),
      (blocked:PlantItem {tag: 'GTV-43015'})
RETURN EXISTS {
  MATCH (a) ((u:PlantItem)-[:line_to]->(v:PlantItem) WHERE u <> blocked AND v <> blocked)+ (b)
} AS reachable

MATCH (u:Valve)-[:line_to*1..]->(:PlantItem {tag: 'P-5501A'})
RETURN DISTINCT u.tag AS tag
ORDER BY tag;

MATCH (v:PlantItem:SwingCheckValve {unit_id: '42'})
RETURN v.tag AS tag
ORDER BY tag;

MATCH (e:Equipment)-[:measured_by]->(sensor:PlantItem)
WHERE EXISTS {
  (sensor)-[:send_signal_to*0..]->(:ProcessInstrumentationFunction {loop_tag: 'PI-9048'})
}
RETURN DISTINCT e.tag AS tag
ORDER BY tag

MATCH (loop:ProcessControlFunction {loop_tag: 'LIC-48065'})-[:send_signal_to*1..]->(actuator:PlantItem {kind: 'actuator'})-[:control]->(valve:Valve)
RETURN DISTINCT valve.tag AS tag
ORDER BY tag;

MATCH (v:Valve)-[:line_to*1..]->(d:PlantItem {tag: 'D-2701'})
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (p:PlantItem {tag: 'P-6101C'})-[:line_to*1..]->(v:PlantItem:Valve)
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (v:PlantItem:AngleBallValve {unit_id: '10'})
RETURN v.tag AS tag
ORDER BY tag;

MATCH (v:PlantItem:BallValve {unit_id: '10'})
RETURN v.tag AS tag
ORDER BY tag;

MATCH (loop:ProcessInstrumentationFunction {loop_tag: 'PIC-60027'})-[:send_signal_to*1..]->(actuator:PlantItem {kind: 'actuator'})-[:control]->(valve:Valve)
RETURN DISTINCT valve.tag AS tag
ORDER BY tag;

MATCH (loop:ProcessInstrumentationFunction {loop_tag: 'LIC-55001'})-[:send_signal_to*]->(actuator:ActuatingFunction)-[:control]->(valve:Valve)
RETURN DISTINCT valve.tag AS tag
ORDER BY tag;

MATCH (a:PlantItem {tag: 'E-4601'}), (b:PlantItem {tag: 'V-4601'})
RETURN a.tag AS from_tag, b.tag AS to_tag,
       EXISTS {
         MATCH (a) ((x:PlantItem)-[:line_to]->(y:PlantItem)
                    WHERE x.tag <> 'XV-46025' AND y.tag <> 'XV-46025'){1,} (b)
       } AS reachable

MATCH (a:PlantItem {tag: 'P-1003'}), (b:PlantItem {tag: 'TK-1101'}), (gv:PlantItem {tag: 'GV-10003'})
RETURN a.tag AS from_tag, b.tag AS to_tag,
       EXISTS {
         MATCH (a) ((x:PlantItem)-[:line_to]->(y:PlantItem) WHERE y <> gv)+ (b)
       } AS can_flow_without_valve

MATCH (a:PlantItem {tag: 'D-1501'}), (b:PlantItem {tag: 'EA-1501'}), (v:PlantItem:Valve)
WHERE EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (start:PlantItem {tag: 'D-6001'}), (finish:PlantItem {tag: 'TK-6202'}), (v:Valve)
WHERE EXISTS { (start)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(finish) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag, tag

MATCH (a:PlantItem {tag: 'D-1001'}), (b:PlantItem {tag: 'E-1201'})
RETURN a.tag AS source_tag, b.tag AS target_tag,
       EXISTS { (a)-[:line_to*1..]->(b) } AS reachable;

MATCH (a:PlantItem {tag: 'P-6001A'}), (b:PlantItem {tag: 'P-6101A'}), (v:Valve)
WHERE EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (a:PlantItem {tag: 'F-1701B'}), (b:PlantItem {tag: 'V-2601'})
RETURN a.tag AS source_tag, b.tag AS target_tag,
       EXISTS {
         MATCH (a)((x:PlantItem)-[:line_to]->(y:PlantItem) WHERE y.tag <> 'V-2101')+(b)
       } AS reachable_without_V_2101

MATCH (a:PlantItem {tag: 'P-4101A'}), (b:PlantItem {tag: 'TK-4402'}), (v:Valve)
WHERE EXISTS { (a)-[:line_to*0..]->(v) }
  AND EXISTS { (v)-[:line_to*0..]->(b) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (a:PlantItem {tag: 'TK-602'}), (b:PlantItem {tag: 'V-1301'}), (v:Valve)
WHERE v <> b
  AND EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (a:PlantItem {tag: 'E-901'}), (b:PlantItem {tag: 'E-4801'})
RETURN a.tag AS from_tag, b.tag AS to_tag,
       EXISTS {
         MATCH (a) ((x)-[:line_to]->(y) WHERE y.tag <> 'BFV-12001')+ (b)
       } AS can_flow_without_valve

MATCH (a:PlantItem {tag: 'T-2701'}), (b:PlantItem {tag: 'P-4201B'}), (v:Valve)
WHERE EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (a:PlantItem {tag: 'V-3501'}), (b:PlantItem {tag: 'P-3501B'})
RETURN a.tag AS from_tag, b.tag AS to_tag,
       EXISTS {
         MATCH (a) ((x:PlantItem)-[:line_to]->(y:PlantItem) WHERE y.tag <> 'GTV-35004')+ (b)
       } AS reachable

MATCH (a:PlantItem {tag: 'K-6001'}), (b:PlantItem {tag: 'CHV-29004'})
MATCH p = shortestPath((a)-[:line_to*]->(b))
RETURN [n IN nodes(p) | n.tag] AS tags;

MATCH (:PlantItem {tag: 'GV-45002'})-[:line_to]->(item:PlantItem)
RETURN DISTINCT item.tag AS tag
ORDER BY tag;

MATCH (:PlantItem {tag: 'T-4801'})-[:line_to]->(item:PlantItem)
RETURN DISTINCT item.tag AS tag
ORDER BY tag;

MATCH (:PlantItem:Valve {tag: 'GTV-2006'})-[:line_to]->(fed:PlantItem)
RETURN fed.tag AS tag
ORDER BY tag;

MATCH (f:ProcessInstrumentationFunction {loop_tag: 'LSHH-16006'})-[:send_signal_to*1..]->(a:ActuatingFunction)-[:control]->(v:Valve)
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (c:ProcessControlFunction {loop_tag: 'LIC-48065'})-[:send_signal_to*1..]->(a:PlantItem {kind: 'actuator'})-[:control]->(v:Valve)
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (loop:ProcessControlFunction {loop_tag: 'PIC-25027'})-[:send_signal_to*1..]->(actuator:PlantItem)-[:control]->(valve:Valve)
RETURN DISTINCT valve.tag AS tag
ORDER BY tag;

MATCH (loop:ProcessInstrumentationFunction {loop_tag: 'PIC-60027'})-[:send_signal_to*1..]->(actuator:PlantItem {kind: 'actuator'})-[:control]->(valve:Valve)
RETURN DISTINCT valve.tag AS tag
ORDER BY tag;

MATCH (v:PlantItem:Valve)-[:line_to*1..]->(p:PlantItem {tag: 'P-401B'})
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (v:Valve)-[:line_to*1..]->(target:PlantItem {tag: 'V-4001'})
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (v:Valve)-[:line_to*1..]->(:PlantItem {tag: 'P-5501A'})
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (v:PlantItem:Valve)-[:line_to*1..]->(e:PlantItem {tag: 'E-5002'})
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (p:PlantItem:CentrifugalPump {unit_id: '61'})
RETURN p.tag AS tag
ORDER BY tag;
